```verilog
module TopModule (
    input        clk,
    input        load,
    input  [511:0] data,
    output reg [511:0] q
);

    // Rule 110: index = {left, center, right}
    // 111->0, 110->1, 101->1, 100->0, 011->1, 010->1, 001->1, 000->0  => 8'h6E
    localparam [7:0] RULE_110 = 8'b01101110;

    wire [511:0] next_q;

    // Zero padding: padded_q[i+1] = q[i], padded_q[0] = q[-1] = 0, padded_q[513] = q[512] = 0
    wire [513:0] padded_q = {1'b0, q, 1'b0};

    genvar i;
    generate
        for (i = 0; i < 512; i = i + 1) begin : rule110_gen
            // left = q[i+1], center = q[i], right = q[i-1]
            assign next_q[i] = RULE_110[{padded_q[i+2], padded_q[i+1], padded_q[i]}];
        end
    endgenerate

    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

endmodule
```

**Explanation:**
- The 512-bit state `q` is padded with zeros on both sides (`{1'b0, q, 1'b0}`), which implements the "boundaries are zero" assumption without any out-of-range indexing.
- For each cell `i`, the neighborhood is `{q[i+1], q[i], q[i-1]}`, i.e. `{padded_q[i+2], padded_q[i+1], padded_q[i]}`. This 3-bit value indexes the Rule 110 lookup table `8'h6E` (binary `01101110`), matching the truth table exactly.
- The register updates synchronously on the positive clock edge: `load` (active high) loads `data`, otherwise the automaton advances one step.
